code.cpp:
class Solution {
public:
    long long maxDifference(vector<int>& nums) {
        int n = nums.size();
        vector<long long> dp(n + 1, 0);          // dp[n] = 0 already
        for (int i = n - 1; i >= 0; --i) {
            long long best = LLONG_MIN;
            long long s1 = nums[i];
            if (s1 % 3 == 0)
                best = max(best, s1 - dp[i + 1]);
            else
                best = max(best, s1 + dp[i + 1]);
            if (i + 1 < n) {
                long long s2 = s1 + nums[i + 1];
                if (s2 % 3 == 0)
                    best = max(best, s2 - dp[i + 2]);
                else
                    best = max(best, s2 + dp[i + 2]);
            }
            dp[i] = best;
        }
        return dp[0];
    }
};
